INSERT INTO `ai_kb_evaluation` (`id`, `owner_id`, `kb_id`, `request_id`, `request_signature`, `dataset_key`, `dataset_sha256`, `group_key`, `status`, `case_count`, `completed_count`, `failed_count`, `stop_requested`, `corpus_verified`, `error`, `dataset_snapshot`, `bindings`, `run_context`, `observations`, `lease_token`, `lease_expires_at`, `started_at`, `completed_at`, `created_at`, `updated_at`) VALUES (4,1,5,'6ef3752d-df0b-407f-8eda-f7b37812f6b4','020ac8b8819d2f7762a1834e3574f5aa969eb3ff4cf9eb3b2f079355c0169291','business-cases','f3a4016eabc10a974e3acffc6d7347477976d00923c196c608de55a6db99538b','project_ops','succeeded',1,1,0,0,1,'','{\n  \"version\": 1,\n  \"description\": \"基于本仓库实际项目文档的32题AI辅助业务题集：development20题、validation12题，24个有据问题与8个指定库资料不足问题。不是真实用户历史问题，没有真人签署；预留分组仅在首次真实运行前未参与调优，规则筛查不等于语义准确率。\",\n  \"annotation\": {\n    \"source_kind\": \"actual_project_document_excerpts\",\n    \"authoring\": \"ai_assisted\",\n    \"human_signed\": false,\n    \"actual_user_history\": false,\n    \"source_revision\": \"fc226fbc8d1cd196453617fa7ff2fcdb548ba945\",\n    \"reserved_split\": \"validation\",\n    \"reservation_note\": \"validation只表示初始预留分组；真实运行或用于调优后应在测量记录中标记首次使用时间，不自动宣称独立验收。\"\n  },\n  \"documents\": [\n    {\n      \"key\": \"ops-environment\",\n      \"kb\": \"project_ops\",\n      \"source\": \"ai_document/ai-rag/business-docs/01-开发环境与配置.md\",\n      \"title\": \"开发环境与配置\",\n      \"sha256\": \"ce3eb80aaefee71f0ee2ff7aeddf94d1c9860ef3fd6b051bfb6d76ff7d988d1d\"\n    },\n    {\n      \"key\": \"ops-data\",\n      \"kb\": \"project_ops\",\n      \"source\": \"ai_document/ai-rag/business-docs/02-数据初始化与备份.md\",\n      \"title\": \"数据初始化与备份\",\n      \"sha256\": \"3a9e4b7849bc7986497cca644e2f97ee6415ec94005165d478b84d4e933dce39\"\n    },\n    {\n      \"key\": \"ops-build\",\n      \"kb\": \"project_ops\",\n      \"source\": \"ai_document/ai-rag/business-docs/03-构建启动与验收.md\",\n      \"title\": \"构建启动与验收\",\n      \"sha256\": \"b9ef7fe283e6d5a7e2f3fef4ac3b83195a210defba8874fed97feb4fb54cb8a2\"\n    },\n    {\n      \"key\": \"ops-cleanup\",\n      \"kb\": \"project_ops\",\n      \"source\": \"ai_document/ai-rag/business-docs/04-临时资源清理.md\",\n      \"title\": \"临时资源清理\",\n      \"sha256\": \"1bfe5d2b323965c686051cf238cc659d89b48705590ab25f14de7f4a21135ea7\"\n    },\n    {\n      \"key\": \"ai-models\",\n      \"kb\": \"project_ai\",\n      \"source\": \"ai_document/ai-rag/business-docs/05-模型与向量存储.md\",\n      \"title\": \"模型与向量存储\",\n      \"sha256\": \"bdbe896880111a07df8e71a23225588a68c4738245ac343ccdcc038ac48377c3\"\n    },\n    {\n      \"key\": \"ai-knowledge\",\n      \"kb\": \"project_ai\",\n      \"source\": \"ai_document/ai-rag/business-docs/06-知识库资料与回答.md\",\n      \"title\": \"知识库资料与回答\",\n      \"sha256\": \"f88c7abd52edbd4f9512f62ac43bc8f1bd80439a91672e8646a9d42a1eb4dea7\"\n    },\n    {\n      \"key\": \"ai-workflows\",\n      \"kb\": \"project_ai\",\n      \"source\": \"ai_document/ai-rag/business-docs/07-常用流程与运行记录.md\",\n      \"title\": \"常用流程与运行记录\",\n      \"sha256\": \"9d44db5fc5ec567a98b8e80e21a48fa2e4e20375863195ed55032b84fee49e11\"\n    },\n    {\n      \"key\": \"ai-access\",\n      \"kb\": \"project_ai\",\n      \"source\": \"ai_document/ai-rag/business-docs/08-身份权限与数据隔离.md\",\n      \"title\": \"身份权限与数据隔离\",\n      \"sha256\": \"9e98bad2f29114f1536cd386c48f73bfce8d831879a099644bb06eca3c4039dc\"\n    }\n  ],\n  \"cases\": [\n    {\n      \"id\": \"business-dev-compose-config\",\n      \"split\": \"development\",\n      \"category\": \"direct\",\n      \"kb\": \"project_ops\",\n      \"query\": \"本项目使用Compose启动时，配置从哪里加载，容器连接服务用什么地址？AI和App的环境变量从哪里注入？\",\n      \"expected_documents\": [\n        \"ops-environment\"\n      ],\n      \"evidence\": [\n        {\n          \"document\": \"ops-environment\",\n          \"groups\": [\n            [\n              \"后端 `docker/etc/*.yaml`\"\n            ],\n            [\n              \"使用容器服务名\"\n            ],\n            [\n              \"AI/App 的 `env_file` 注入后端 `.env.local`\"\n            ]\n          ]\n        }\n      ],\n      \"answer\": {\n        \"kind\": \"answerable\",\n        \"required_groups\": [\n          [\n            \"docker/etc/*.yaml\",\n            \"docker/etc/\"\n          ],\n          [\n            \"容器服务名\",\n            \"服务名\"\n          ],\n          [\n            \"env_file\"\n          ],\n          [\n            \".env.local\"\n          ]\n        ],\n        \"forbidden_phrases\": []\n      },\n      \"rationale\": \"实际开发手册的配置双套制表给出容器配置、地址及环境变量注入，不能混成宿主配置。\"\n    },\n    {\n      \"id\": \"business-dev-literal-yaml\",\n      \"split\": \"development\",\n      \"category\": \"paraphrase\",\n      \"kb\": \"project_ops\",\n      \"query\": \"我在终端设了一个同名环境变量，YAML里直填的值就会被覆盖吗？占位符要通过什么加载能力才会展开？\",\n      \"expected_documents\": [\n        \"ops-environment\"\n      ],\n      \"evidence\": [\n        {\n          \"document\": \"ops-environment\",\n          \"groups\": [\n            [\n              \"不因同名环境变量存在而自动覆盖\"\n            ],\n            [\n              \"仅启用 `conf.UseEnv()` 的加载入口展开\"\n            ]\n          ]\n        }\n      ],\n      \"answer\": {\n        \"kind\": \"answerable\",\n        \"required_groups\": [\n          [\n            \"不因同名环境变量存在而自动覆盖\",\n            \"不会自动覆盖\",\n            \"不自动覆盖\"\n          ],\n          [\n            \"conf.UseEnv()\"\n          ]\n        ],\n        \"forbidden_phrases\": []\n      },\n      \"rationale\": \"直填与占位符是两种明确语义，题目要求保留适用条件。\"\n    },\n    {\n      \"id\": \"business-dev-env-recreate\",\n      \"split\": \"development\",\n      \"category\": \"paraphrase\",\n      \"kb\": \"project_ops\",\n      \"query\": \"给Compose换了.env.local里面的配置以后，只restart容器能读到新值吗？租户会自动取得平台凭据吗？\",\n      \"expected_documents\": [\n        \"ops-environment\"\n      ],\n      \"evidence\": [\n        {\n          \"document\": \"ops-environment\",\n          \"groups\": [\n            [\n              \"env 变更须重新创建相关容器\"\n            ],\n            [\n              \"单独 restart 不更新环境\"\n            ],\n            [\n              \"租户不自动继承平台凭据\"\n            ]\n          ]\n        }\n      ],\n      \"answer\": {\n        \"kind\": \"answerable\",\n        \"required_groups\": [\n          [\n            \"重新创建相关容器\",\n            \"重新创建容器\",\n            \"重建相关容器\"\n          ],\n          [\n            \"restart不更新环境\",\n            \"restart不会更新环境\",\n            \"restart不能更新环境\",\n            \"重启不会更新环境\"\n          ],\n          [\n            \"租户不自动继承平台凭据\",\n            \"不会自动继承平台凭据\",\n            \"不自动继承平台凭据\"\n          ]\n        ],\n        \"forbidden_phrases\": []\n      },\n      \"rationale\": \"手册明确要求重建运行环境且租户不继承平台凭据，不推测实际凭据值。\"\n    },\n    {\n      \"id\": \"business-dev-existing-database\",\n      \"split\": \"development\",\n      \"category\": \"direct\",\n      \"kb\": \"project_ops\",\n      \"query\": \"已有数据卷启动后会自动更新数据库表吗？生成model时能重新导入mysql-all.sql清空现有业务库吗？\",\n      \"expected_documents\": [\n        \"ops-data\"\n      ],\n      \"evidence\": [\n        {\n          \"document\": \"ops-data\",\n          \"groups\": [\n            [\n              \"已有卷不自动覆盖或更新结构\"\n            ],\n            [\n              \"不为生成代码清空业务库\"\n            ],\n            [\n              \"初始化 SQL 会 DROP 并重建业务表\"\n            ]\n          ]\n        }\n      ],\n      \"answer\": {\n        \"kind\": \"answerable\",\n        \"required_groups\": [\n          [\n            \"已有卷不自动覆盖或更新结构\",\n            \"已有卷不自动更新\",\n            \"已有数据卷不会自动更新\",\n            \"不会自动更新结构\"\n          ],\n          [\n            \"不为生成代码清空业务库\",\n            \"不能清空现有业务库\",\n            \"不能重导\",\n            \"不得清空业务库\"\n          ],\n          [\n            \"DROP并重建业务表\",\n            \"删除并重建业务表\",\n            \"删除重建业务表\"\n          ]\n        ],\n        \"forbidden_phrases\": []\n      },\n      \"rationale\": \"实际初始化规则区分新库与已有库，禁止把生成代码变成业务库重置。\"\n    },\n    {\n      \"id\": \"business-dev-backup-partial\",\n      \"split\": \"development\",\n      \"category\": \"partial_unknown\",\n      \"kb\": \"project_ops\",\n      \"query\": \"数据库备份需要记录哪些导出信息、在哪里验证恢复？另外，本机最近一次备份实际是几点完成的？\",\n      \"expected_documents\": [\n        \"ops-data\"\n      ],\n      \"evidence\": [\n        {\n          \"document\": \"ops-data\",\n          \"groups\": [\n            [\n              \"记录来源、导出时间与文件校验值\"\n            ],\n            [\n              \"在独立环境恢复验证\"\n            ]\n          ]\n        }\n      ],\n      \"answer\": {\n        \"kind\": \"answerable\",\n        \"required_groups\": [\n          [\n            \"来源\"\n          ],\n          [\n            \"导出时间\"\n          ],\n          [\n            \"文件校验值\",\n            \"校验值\",\n            \"校验和\",\n            \"哈希\"\n          ],\n          [\n            \"独立环境恢复验证\",\n            \"独立环境验证恢复\",\n            \"隔离环境恢复验证\"\n          ]\n        ],\n        \"forbidden_phrases\": [\n          \"本机最近一次备份在凌晨2点完成\"\n        ],\n        \"absence_policy\": \"required\"\n      },\n      \"rationale\": \"手册给出备份记录与恢复环境，但没有本机最近一次备份的实际完成时间，必须单独说明该未知项。\"\n    },\n    {\n      \"id\": \"business-dev-local-captcha\",\n      \"split\": \"development\",\n      \"category\": \"multi_fact\",\n      \"kb\": \"project_ops\",\n      \"query\": \"AI本地开发免图形验证码要改哪个副本字段？账号密码和权限是否仍校验，能把这份覆盖配置用于生产吗？\",\n      \"expected_documents\": [\n        \"ops-data\"\n      ],\n      \"evidence\": [\n        {\n          \"document\": \"ops-data\",\n          \"groups\": [\n            [\n              \"只把副本的 `Captcha.Enabled` 改为 `false`\"\n            ],\n            [\n              \"账号密码和会话/权限仍正常校验\"\n            ],\n            [\n              \"远程/生产/租户启动不使用这个本地覆盖文件\"\n            ]\n          ]\n        }\n      ],\n      \"answer\": {\n        \"kind\": \"answerable\",\n        \"required_groups\": [\n          [\n            \"Captcha.Enabled\"\n          ],\n          [\n            \"false\"\n          ],\n          [\n            \"账号密码和会话/权限仍正常校验\",\n            \"账号密码、会话和权限仍校验\",\n            \"账号密码和会话权限仍正常校验\",\n            \"账号密码、会话、权限仍然校验\"\n          ],\n          [\n            \"远程/生产/租户启动不使用这个本地覆盖文件\",\n            \"不用于生产\",\n            \"不能用于生产\",\n            \"生产不使用\"\n          ]\n        ],\n        \"forbidden_phrases\": []\n      },\n      \"rationale\": \"限定在本地副本与既有认证校验，不能解释为免密码或生产默认关闭验证码。\"\n    },\n    {\n      \"id\": \"business-dev-build-source\",\n      \"split\": \"development\",\n      \"category\": \"direct\",\n      \"kb\": \"project_ops\",\n      \"query\": \"改了后端Go源码后，docker compose --build会自动编译吗？正确流程要先运行哪个构建脚本？\",\n      \"expected_documents\": [\n        \"ops-build\"\n      ],\n      \"evidence\": [\n        {\n          \"document\": \"ops-build\",\n          \"groups\": [\n            [\n              \"只复制宿主预编译的 Linux 二进制\"\n            ],\n            [\n              \"**不会编译 Go 源码**\"\n            ],\n            [\n              \"data/scripts/build-images.ps1\"\n            ]\n          ]\n        }\n      ],\n      \"answer\": {\n        \"kind\": \"answerable\",\n        \"required_groups\": [\n          [\n            \"只复制宿主预编译的Linux二进制\",\n            \"复制宿主预编译\",\n            \"复制已编译的Linux二进制\"\n          ],\n          [\n            \"不会编译Go源码\",\n            \"不自动编译Go\",\n            \"不会自动编译Go\"\n          ],\n          [\n            \"data/scripts/build-images.ps1\",\n            \"build-images.ps1\"\n          ]\n        ],\n        \"forbidden_phrases\": []\n      },\n      \"rationale\": \"构建启动章节说明镜像仅复制宿主产物，构建失败不得部署旧二进制。\"\n    },\n    {\n      \"id\": \"business-dev-ready-acceptance\",\n      \"split\": \"development\",\n      \"category\": \"multi_fact\",\n      \"kb\": \"project_ops\",\n      \"query\": \"容器Up、/ready通过并且前端HTML返回200，是否说明AI功能已经验收？还需要核对哪些运行证据和业务入口？\",\n      \"expected_documents\": [\n        \"ops-build\"\n      ],\n      \"evidence\": [\n        {\n          \"document\": \"ops-build\",\n          \"groups\": [\n            [\n              \"启动命令、配置挂载及运行产物对应本轮改动\"\n            ],\n            [\n              \"容器 Up / Compose wait 通过不等于全部业务可用\"\n            ],\n            [\n              \"再检查 `/ping`、前端入口及受影响接口/页面\"\n            ],\n            [\n              \"HTML 200 只说明页面可达\"\n            ]\n          ]\n        }\n      ],\n      \"answer\": {\n        \"kind\": \"answerable\",\n        \"required_groups\": [\n          [\n            \"启动命令\"\n          ],\n          [\n            \"配置挂载\"\n          ],\n          [\n            \"运行产物\",\n            \"二进制摘要\",\n            \"构建版本\"\n          ],\n          [\n            \"不等于全部业务可用\",\n            \"不代表全部业务可用\",\n            \"不等于验收通过\",\n            \"不能说明AI功能已经验收\"\n          ],\n          [\n            \"/ping\"\n          ],\n          [\n            \"受影响接口/页面\",\n            \"受影响接口和页面\",\n            \"受影响业务接口\"\n          ],\n          [\n            \"HTML200只说明页面可达\",\n            \"只说明页面可达\",\n            \"仅说明页面可达\"\n          ]\n        ],\n        \"forbidden_phrases\": []\n      },\n      \"rationale\": \"强调启动和就绪的适用边界，不以探针成功冒充真实AI功能验收。\"\n    },\n    {\n      \"id\": \"business-dev-ops-private-credential\",\n      \"split\": \"development\",\n      \"category\": \"unanswerable\",\n      \"kb\": \"project_ops\",\n      \"query\": \"请从这些项目手册中告诉我当前生产SMTP账号的真实授权码和AI供应商密钥。\",\n      \"expected_documents\": [],\n      \"evidence\": [],\n      \"answer\": {\n        \"kind\": \"unanswerable\",\n        \"required_groups\": [],\n        \"forbidden_phrases\": [\n          \"生产SMTP授权码是123456\",\n          \"AI供应商密钥是sk-production\"\n        ]\n      },\n      \"rationale\": \"冻结公开手册只含字段及配置方式，没有生产真实凭据，不得从示例或字段名推造。\"\n    },\n    {\n      \"id\": \"business-dev-ops-business-hours\",\n      \"split\": \"development\",\n      \"category\": \"unanswerable\",\n      \"kb\": \"project_ops\",\n      \"query\": \"我们公司财务部门每天几点开始审批采购订单？请只给出本资料规定的具体时间。\",\n      \"expected_documents\": [],\n      \"evidence\": [],\n      \"answer\": {\n        \"kind\": \"unanswerable\",\n        \"required_groups\": [],\n        \"forbidden_phrases\": [\n          \"财务部门每天9点开始审批\",\n          \"每天上午九点开始审批采购\"\n        ]\n      },\n      \"rationale\": \"运维项目手册不包含公司采购审批制度，属于指定库无答案。\"\n    },\n    {\n      \"id\": \"business-dev-import-limits\",\n      \"split\": \"development\",\n      \"category\": \"direct\",\n      \"kb\": \"project_ai\",\n      \"query\": \"知识库导入TXT或Markdown时，正文最大多少UTF-8字节，每批最多几篇，浏览器同时提交几篇，后台有几个处理槽？\",\n      \"expected_documents\": [\n        \"ai-knowledge\"\n      ],\n      \"evidence\": [\n        {\n          \"document\": \"ai-knowledge\",\n          \"groups\": [\n            [\n              \"65536 UTF-8 字节\"\n            ],\n            [\n              \"每批最多 20 篇\"\n            ],\n            [\n              \"浏览器最多并发提交 2 篇\"\n            ],\n            [\n              \"服务端有 2 个后台处理槽\"\n            ]\n          ]\n        }\n      ],\n      \"answer\": {\n        \"kind\": \"answerable\",\n        \"required_groups\": [\n          [\n            \"65536\"\n          ],\n          [\n            \"每批最多20篇\",\n            \"每批20篇\",\n            \"一批最多20篇\"\n          ],\n          [\n            \"浏览器最多并发提交2篇\",\n            \"浏览器同时提交2篇\",\n            \"浏览器最多同时2篇\",\n            \"浏览器并发2篇\"\n          ],\n          [\n            \"2个后台处理槽\",\n            \"后台2个处理槽\",\n            \"后台有两个处理槽\"\n          ]\n        ],\n        \"forbidden_phrases\": []\n      },\n      \"rationale\": \"导入容量以字节和文档数分别计，浏览器提交并发与后台处理槽应分别说明。\"\n    },\n    {\n      \"id\": \"business-dev-import-receipt\",\n      \"split\": \"development\",\n      \"category\": \"paraphrase\",\n      \"kb\": \"project_ai\",\n      \"query\": \"导入窗口提示接收成功就能关闭吗？queued是不是已经可检索？停止批次后已经开始的作业会怎样？\",\n      \"expected_documents\": [\n        \"ai-knowledge\"\n      ],\n      \"evidence\": [\n        {\n          \"document\": \"ai-knowledge\",\n          \"groups\": [\n            [\n           